def _segment_info(zone, y):
    if zone == 'head': return ('头面颈项部', '浅刺0.2~0.5寸或平刺，避开眼球、颈动脉窦及延髓危险区，严禁深刺。')
    if zone == 'hand': return ('腕掌指端部', '浅刺0.1~0.3寸或点刺出血，腕掌部避开桡尺动脉及正中神经。')
    if zone == 'foot': return ('足踝趾端部', '浅刺0.1~0.5寸或点刺，足背及内踝避开足背动脉与胫后血管神经。')
    if zone == 'arm' and y >= 1.25: return ('上肢肩臂段', '直刺0.5~1.2寸，肩胛及腋窝周围避开胸膜顶与腋神经血管束。')
    if zone == 'arm' and y >= 1.03: return ('上肢肘及前臂段', '直刺0.5~1.0寸，避开尺神经沟、肱动脉及骨间神经。')
    if zone == 'arm': return ('上肢腕部段', '直刺0.3~0.5寸，避开桡动脉搏动处及腕管正中神经。')
    if zone == 'torso_back' and y >= 1.15: return ('背部胸椎段', '向脊柱斜刺或平刺0.5~0.8寸，严禁直刺深刺以防气胸。')
    if zone == 'torso_back': return ('腰骶段', '直刺0.8~1.5寸，腰部注意肾区安全深度，骶孔穴位适度进针。')
    if zone == 'torso_front' and y >= 1.20: return ('胸部肋间段', '沿肋间隙斜刺或平刺0.3~0.5寸，严禁直刺深刺以防气胸及心包损伤。')
    if zone == 'torso_front': return ('腹部及少腹段', '直刺0.8~1.5寸，孕妇少腹慎针，空腹及膀胱充盈时注意深度。')
    if zone == 'leg_front' and y >= 0.48: return ('下肢股前内侧段', '直刺1.0~1.8寸，股三角区避开股动静脉及股神经。')
    if zone == 'leg_front': return ('下肢膝下前外侧段', '直刺0.8~1.5寸，腓骨小头旁避开腓总神经。')
    if zone == 'leg_back' and y >= 0.48: return ('下肢臀股后外侧段', '直刺1.2~2.5寸，坐骨神经行经处避免暴力提插。')
    if zone == 'leg_back': return ('下肢腘窝及小腿后侧段', '直刺0.8~1.5寸，腘窝避开腘动脉与胫神经，跟腱旁防伤肌腱。')
    return ZONE_ZH.get(zone, ('体表循行区', '配合骨度分寸及解剖层次规范进针。'))

